DROP TABLE IF EXISTS `naruto_classes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `naruto_classes` (
  `id` tinyint(3) unsigned NOT NULL COMMENT '1 Ninjutsu, 2 Taijutsu, 3 Genjutsu (nomes em control.classNname)',
  `dano_fisico` smallint(6) NOT NULL DEFAULT 0,
  `critico` smallint(6) NOT NULL DEFAULT 0,
  `dano_jutsu` smallint(6) NOT NULL DEFAULT 0,
  `dano_elemental` smallint(6) NOT NULL DEFAULT 0,
  `vantagem_elemento` smallint(6) NOT NULL DEFAULT 0,
  `defesa_fisica` smallint(6) NOT NULL DEFAULT 0,
  `chance_efeito` smallint(6) NOT NULL DEFAULT 0,
  `duracao_efeito` smallint(6) NOT NULL DEFAULT 0,
  `valor_efeito` smallint(6) NOT NULL DEFAULT 0,
  `dreno` smallint(6) NOT NULL DEFAULT 0,
  `resist_debuff` smallint(6) NOT NULL DEFAULT 0,
  `economia_tecnica` smallint(6) NOT NULL DEFAULT 0,
  `sj_ataque` smallint(6) NOT NULL DEFAULT 0,
  `sj_defesa` smallint(6) NOT NULL DEFAULT 0,
  `sj_dano_fisico` smallint(6) NOT NULL DEFAULT 0,
  `sj_critico` smallint(6) NOT NULL DEFAULT 0,
  `sj_dano_elemental` smallint(6) NOT NULL DEFAULT 0,
  `sj_economia` smallint(6) NOT NULL DEFAULT 0,
  `sj_chance_efeito` smallint(6) NOT NULL DEFAULT 0,
  `sj_duracao_efeito` smallint(6) NOT NULL DEFAULT 0,
  `sj_resist_debuff` smallint(6) NOT NULL DEFAULT 0,
  `descricao` text NOT NULL,
  `descricao_en` text NOT NULL,
  `buff_proprio` smallint(6) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

INSERT INTO `naruto_classes` VALUES
(1,0,0,0,26,65,-5,0,0,0,0,0,0,8,15,0,0,20,20,0,0,0,'Mestre dos elementos. Jutsus com elemento causam mais dano e a vantagem de elemento pesa mais; é quem mais ganha Chakra a cada nível. Fraqueza: defesa física um pouco menor (recebe mais dano de ataques físicos).','Master of the elements. Elemental jutsus deal more damage and elemental advantage hits harder; gains the most Chakra per level. Weakness: lower physical defense (takes more damage from physical attacks).',0),
(2,6,8,0,0,0,0,0,0,0,0,-20,25,15,15,10,5,0,0,0,0,0,'Especialista do corpo a corpo. Ataques físicos causam mais dano e acertam críticos com mais frequência, os jutsus de Taijutsu saem do Poder de Ataque (sem elemento), as técnicas sem elemento custam menos Chakra e é quem mais ganha HP a cada nível. Não tem fraqueza de elemento: ataques de elemento nunca causam dano extra nele. Fraqueza: pouca resistência a genjutsu (efeitos negativos de outros ninjas pegam mais forte).','Close-combat specialist. Physical attacks deal more damage and crit more often, Taijutsu jutsus are powered by Attack Power (no element), non-elemental techniques cost less Chakra, and gains the most HP per level. Has no elemental weakness: elemental attacks never deal extra damage to them. Weakness: poor genjutsu resistance (negative effects from other ninjas hit harder).',0),
(3,4,0,-3,0,0,0,37,1,36,60,21,0,0,25,8,0,0,0,20,1,25,'Mestre do controle. Atordoamentos, venenos, queimaduras e enfraquecimentos pegam com mais frequência, duram mais e são mais fortes; o Dreno de Chakra rouba mais, os jutsus que reforçam você (ataque, defesa, escudo, regeneração) ficam mais fortes e resiste aos efeitos dos inimigos. Fraqueza: menos dano direto com jutsus.','Master of control. Stuns, poisons, burns and weakenings land more often, last longer and hit harder; Chakra Drain steals more, jutsus that buff yourself (attack, defense, shield, regeneration) are stronger, and resists enemy effects. Weakness: less direct jutsu damage.',30);
