  `pvpondedrop` tinyint(1) unsigned NOT NULL DEFAULT 1 COMMENT '0 = só mochila, 1 = mochila e equipados',
  `pvpprotegervariantes` tinyint(1) unsigned NOT NULL DEFAULT 1,
  `pvpmaxitens` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `pvpperdaryou` tinyint(3) unsigned NOT NULL DEFAULT 10,
  `pvpbrancahoras` smallint(5) unsigned NOT NULL DEFAULT 24,
  `pvpbrancachance` tinyint(3) unsigned NOT NULL DEFAULT 25,
  `pvpvermelhamortes` tinyint(3) unsigned NOT NULL DEFAULT 3,
  `pvpvermelhadias` smallint(5) unsigned NOT NULL DEFAULT 14,
  `pvpvermelhabanco` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `pvpbanirdias` smallint(5) unsigned NOT NULL DEFAULT 30,
  `pvpbanirmetade` tinyint(1) unsigned NOT NULL DEFAULT 1 COMMENT 'banimento automático também destrói metade dos itens',
  `morteryoubase` tinyint(3) unsigned NOT NULL DEFAULT 10,
  `morteryounivel` decimal(5,2) unsigned NOT NULL DEFAULT 1.00,
  `morteryoumax` tinyint(3) unsigned NOT NULL DEFAULT 50,
  `morteexpnivel` decimal(5,2) unsigned NOT NULL DEFAULT 0.50,
  `morteexpmax` tinyint(3) unsigned NOT NULL DEFAULT 25,
  `morteitemnivel` decimal(5,2) unsigned NOT NULL DEFAULT 0.25,
  `morteitemmax` tinyint(3) unsigned NOT NULL DEFAULT 15,
  `mortenivelseguro` smallint(5) unsigned NOT NULL DEFAULT 5,
  `mortelutaabandono` smallint(5) unsigned NOT NULL DEFAULT 5,
  `mortelutachance` tinyint(3) unsigned NOT NULL DEFAULT 50,
  `vendamochila` smallint(5) unsigned NOT NULL DEFAULT 100,
  `pilhaconsumiveis` smallint(5) unsigned NOT NULL DEFAULT 20,
  `compradorvila` tinyint(1) unsigned NOT NULL DEFAULT 1,
  `compradorremoto` smallint(5) unsigned NOT NULL DEFAULT 200,
  `classenivel` smallint(5) unsigned NOT NULL DEFAULT 5 COMMENT 'nível mínimo para escolher a especialização (especializacao.php)',
  `alquimiaperda` tinyint(3) unsigned NOT NULL DEFAULT 50,
  `alquimiaexptaxa` smallint(5) unsigned NOT NULL DEFAULT 100,
  `alquimiacritico` decimal(5,2) unsigned NOT NULL DEFAULT 3.00,
  `alquimiainfusaocusto` mediumint(8) unsigned NOT NULL DEFAULT 1500,
  `linkdoacao` varchar(255) NOT NULL DEFAULT 'https://donate.stripe.com/7sY4gz51905J1nRd8egQE00',
  `linkgithub` varchar(255) NOT NULL DEFAULT 'https://github.com/Oyatsumi/NarutoBrowserMMORPGRework https://github.com/Oyatsumi/NarutoBrowserMmorpg',
  `doacaodias` smallint(5) unsigned NOT NULL DEFAULT 7,
  `idiomasativos` varchar(50) NOT NULL DEFAULT 'pt,en',
  `tpretorno` smallint(5) unsigned NOT NULL DEFAULT 5,
  `tpretornopct` tinyint(3) unsigned NOT NULL DEFAULT 50,
  `tpteleporte` smallint(5) unsigned NOT NULL DEFAULT 30,
  `viagemryou` smallint(5) unsigned NOT NULL DEFAULT 2,
  `epcusto` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `epbonus` tinyint(3) unsigned NOT NULL DEFAULT 15,
  `epnivel` tinyint(3) unsigned NOT NULL DEFAULT 2,
  `tpdescanso` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `epdescanso` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `trocavila_dias` smallint(5) unsigned NOT NULL DEFAULT 30 COMMENT 'dias de espera entre duas trocas de vila natal (0 = sem espera)',
  `trocadif_dias` smallint(5) unsigned NOT NULL DEFAULT 14 COMMENT 'dias de espera entre duas trocas de dificuldade (0 = sem espera)',
  `vilainicial` smallint(5) unsigned NOT NULL DEFAULT 1 COMMENT 'id da vila natal dada aos ninjas novos no cadastro (towns.id com vilanatal = 1)',
  `historicomax` tinyint(3) unsigned NOT NULL DEFAULT 12 COMMENT 'mensagens guardadas/mostradas no histórico do jogador (5 a 30)',
  `pvpcaveiraminutos` smallint(5) unsigned NOT NULL DEFAULT 30 COMMENT 'minutos depois de uma morte injusta em que quem tem caveira fica atacável mesmo offline e não entra em vilas (0 = desligado)',
  `pvpbanirniveis` tinyint(3) unsigned NOT NULL DEFAULT 5,
  `pvpvermelhaperdamin` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `pvpvermelhaperdamax` tinyint(3) unsigned NOT NULL DEFAULT 5,
  `dj_abates` varchar(40) NOT NULL DEFAULT '40,120,300',
  `dj_abatemargem` smallint(5) NOT NULL DEFAULT 5,
  `dj_vitorias` varchar(40) NOT NULL DEFAULT '5,15,40',
  `dj_tele_tpbase` smallint(5) unsigned NOT NULL DEFAULT 20,
  `dj_tele_tp10` smallint(5) unsigned NOT NULL DEFAULT 4,
  `dj_tele_chbase` smallint(5) unsigned NOT NULL DEFAULT 30,
  `dj_tele_ch10` smallint(5) unsigned NOT NULL DEFAULT 5,
  `dj_tele_hpbase` tinyint(3) unsigned NOT NULL DEFAULT 5,
  `dj_tele_hp10` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `dj_tele_max` smallint(5) unsigned NOT NULL DEFAULT 0,
  `fugapenalidade` tinyint(3) unsigned NOT NULL DEFAULT 5,
  `morteexpbase` tinyint(3) unsigned NOT NULL DEFAULT 3,
  `idiomaporip` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `viagemtpbase` smallint(5) unsigned NOT NULL DEFAULT 10 COMMENT 'Viajar Para: TP fixo somado ao TP da vila',
  `viagemtpdist` smallint(5) unsigned NOT NULL DEFAULT 10 COMMENT 'Viajar Para: TP a cada 100 casas de distância',
  `viagemnataltppct` smallint(5) unsigned NOT NULL DEFAULT 300 COMMENT 'vila natal: TP mínimo = % do TP do Pergaminho de Retorno',
  `viagemnatalryoupct` smallint(5) unsigned NOT NULL DEFAULT 400 COMMENT 'vila natal: Ryou mínimo = % do preço do Pergaminho de Retorno',
  `viagemoutraryou` mediumint(8) unsigned NOT NULL DEFAULT 300 COMMENT 'outras vilas: taxa fixa em Ryou',
  `viagemselos` tinyint(3) unsigned NOT NULL DEFAULT 1 COMMENT 'outras vilas: Selos de Viagem gastos (0 = nenhum)',
  `viagemseloitem` mediumint(8) unsigned NOT NULL DEFAULT 436 COMMENT 'id do drop Selo de Viagem',
  `loginip_max` smallint(5) unsigned NOT NULL DEFAULT 3 COMMENT 'contas logadas ao mesmo tempo por IP (0 = sem limite)',
  `durabilidade_ativa` tinyint(1) unsigned NOT NULL DEFAULT 1 COMMENT '1 = cada vitória gasta 1 de durabilidade dos itens finitos',
  `reparo_pct` smallint(5) unsigned NOT NULL DEFAULT 30 COMMENT '% do valor do item cobrado por um reparo completo (proporcional ao que falta)',
  `cla_custo` int(10) unsigned NOT NULL DEFAULT 10000,
  `cla_maxmembros` smallint(5) unsigned NOT NULL DEFAULT 15,
  `cla_meta` int(10) unsigned NOT NULL DEFAULT 200,
  `cla_premio` int(10) unsigned NOT NULL DEFAULT 20000,
  `temporada_dias` smallint(5) unsigned NOT NULL DEFAULT 30,
  `temporada_vitoria` smallint(5) unsigned NOT NULL DEFAULT 10,
  `temporada_derrota` smallint(5) unsigned NOT NULL DEFAULT 3,
  `limitepocoesluta` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `raridade_elite_pct` smallint(5) unsigned NOT NULL DEFAULT 15,
  `raridade_raro_pct` smallint(5) unsigned NOT NULL DEFAULT 30,
  `raridade_drop_elite` smallint(5) unsigned NOT NULL DEFAULT 150,
  `raridade_drop_raro` smallint(5) unsigned NOT NULL DEFAULT 200,
  `raridade_drop_teto` tinyint(3) unsigned NOT NULL DEFAULT 60,
  `roubo_ativo` tinyint(1) unsigned NOT NULL DEFAULT 1,
  `roubo_chance_mochila` tinyint(3) unsigned NOT NULL DEFAULT 3,
  `roubo_chance_equipado` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `status_monstros_ativo` tinyint(1) unsigned NOT NULL DEFAULT 1,
  `status_monstros_mult` smallint(5) unsigned NOT NULL DEFAULT 100,
  `convidado_horas` smallint(5) unsigned NOT NULL DEFAULT 24,
  `convidado_porip` smallint(5) unsigned NOT NULL DEFAULT 5,
  `convidado_ultimalimpeza` int(10) unsigned NOT NULL DEFAULT 0,
  `convidado_ativo` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `lutalog_linhas` tinyint(3) unsigned NOT NULL DEFAULT 15,
  `elemento_bonus` smallint(5) unsigned NOT NULL DEFAULT 20 COMMENT '% de dano nos jutsus do elemento principal (com EP)',
  `elemento_bonus2` smallint(5) unsigned NOT NULL DEFAULT 10 COMMENT '% de dano nos jutsus do elemento secundário (com EP)',
  `elemento_resiste` smallint(5) unsigned NOT NULL DEFAULT 75 COMMENT '% do dano recebido de um jutsu do mesmo elemento',
  `elemento_peso2` smallint(5) unsigned NOT NULL DEFAULT 50 COMMENT '% de peso do elemento secundário do alvo no dano',
  `elemento_nivel` smallint(5) unsigned NOT NULL DEFAULT 5 COMMENT 'nível para escolher os elementos',
  `roubo_ryou_chance` tinyint(3) unsigned NOT NULL DEFAULT 4,
  `roubo_ryou_min` tinyint(3) unsigned NOT NULL DEFAULT 5,
  `roubo_ryou_max` tinyint(3) unsigned NOT NULL DEFAULT 15,
  `roubo_ryou_teto` int(10) unsigned NOT NULL DEFAULT 50,
  `gm_teleporte` tinyint(1) unsigned NOT NULL DEFAULT 1,
  `gm_mapa` tinyint(1) unsigned NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

INSERT INTO `naruto_control` VALUES
(1,'Naruto! Nigeru RPG',400,1,'http://localhost/index.php','admin@localhost',1,'','Ninjutsu','Taijutsu','Genjutsu','Fácil',1,'Médio',1.2,'Difícil',1.5,0,0,1,1,1,1,'O jogo está fechado para manutenção. Por favor volte mais tarde e desculpe o transtorno.','Bem-vindo ao Naruto! Nigeru RPG. Crie sua conta, escolha sua especialização e comece sua jornada ninja!',100,4,1,1,5,'pt',1,1,0,1,30,11,60,2,25,1,1,1,10,24,25,3,14,0,30,1,10,1.00,50,0.50,25,0.25,15,5,5,50,100,20,1,200,5,50,100,3.00,1500,'https://donate.stripe.com/7sY4gz51905J1nRd8egQE00','https://github.com/Oyatsumi/NarutoBrowserMMORPGRework https://github.com/Oyatsumi/NarutoBrowserMmorpg',7,'pt,en',5,50,30,5,1,15,2,1,1,30,14,1,12,30,5,1,5,'40,120,300',5,'5,15,40',20,4,60,10,5,1,0,5,3,1,10,10,300,400,300,1,436,3,1,30,10000,15,200,20000,30,10,3,1,15,30,150,200,60,1,3,1,1,100,24,5,0,1,15,20,10,75,50,5,4,5,15,50,1,1);
DROP TABLE IF EXISTS `naruto_doujutsu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `naruto_doujutsu` (
  `id` tinyint(3) unsigned NOT NULL AUTO_INCREMENT,
  `chave` varchar(20) NOT NULL DEFAULT '',
  `estagio` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `nome` varchar(60) NOT NULL DEFAULT '',
  `imagem` varchar(30) NOT NULL DEFAULT '',
  `ordem` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `custo_ch` smallint(5) unsigned NOT NULL DEFAULT 1,
  `intervalo` smallint(5) unsigned NOT NULL DEFAULT 3,
  `agilidade` smallint(5) unsigned NOT NULL DEFAULT 0,
  `inteligencia` smallint(5) unsigned NOT NULL DEFAULT 0,
  `sorte` smallint(5) unsigned NOT NULL DEFAULT 0,
  `precisao` smallint(5) unsigned NOT NULL DEFAULT 0,
  `esquiva` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `critico` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `ataque` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `defesa` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `ignora_defesa` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `droprate` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `ver_inimigo` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `teleporte` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `reflete` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `ver_mapa` tinyint(3) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `chave_estagio` (`chave`,`estagio`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

