DROP TABLE IF EXISTS `naruto_drops`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `naruto_drops` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL DEFAULT '',
  `mlevel` smallint(5) unsigned NOT NULL DEFAULT 0,
  `type` smallint(5) unsigned NOT NULL DEFAULT 0,
  `attribute1` varchar(30) NOT NULL DEFAULT '',
  `attribute2` varchar(30) NOT NULL DEFAULT '',
  `attribute3` varchar(30) NOT NULL DEFAULT 'X',
  `consumivel` varchar(20) NOT NULL DEFAULT '',
  `ensina_jutsu` smallint(5) unsigned NOT NULL DEFAULT 0,
  `ensina_avatar` smallint(5) unsigned NOT NULL DEFAULT 0,
  `naoVendavel` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `empilhavel` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `maxpilha` smallint(5) unsigned NOT NULL DEFAULT 20,
  `precoloja` mediumint(8) unsigned NOT NULL DEFAULT 0 COMMENT 'preço na loja de consumíveis das vilas (towns.consumiveislist); 0 = não vendido',
  `durabilidade` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'vitórias até quebrar (0 = infinita)',
  `arma_item` smallint(5) unsigned NOT NULL DEFAULT 0,
  `bomba_dano` smallint(5) unsigned NOT NULL DEFAULT 0,
  `bomba_acerto` tinyint(3) unsigned NOT NULL DEFAULT 80,
  `bomba_elemento` varchar(10) NOT NULL DEFAULT 'neutro',
  `bomba_efeito` varchar(20) NOT NULL DEFAULT '',
  `bomba_efeito_valor` smallint(5) unsigned NOT NULL DEFAULT 0,
  `bomba_efeito_turnos` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `bomba_efeito_chance` tinyint(3) unsigned NOT NULL DEFAULT 100,
  `descanso_mult` smallint(5) unsigned NOT NULL DEFAULT 0,
  `descanso_horas` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `banco_limite` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT 'expansão do banco: novo limite de itens (consumivel banco,ID)',
  PRIMARY KEY (`id`),
  KEY `ensina_jutsu` (`ensina_jutsu`),
  KEY `ensina_avatar` (`ensina_avatar`),
  KEY `nome` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=523 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

