DROP TABLE IF EXISTS `naruto_monsters`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `naruto_monsters` (
  `id` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL DEFAULT '',
  `maxhp` smallint(5) unsigned NOT NULL DEFAULT 0,
  `maxdam` smallint(5) unsigned NOT NULL DEFAULT 0,
  `armor` smallint(5) unsigned NOT NULL DEFAULT 0,
  `level` smallint(5) unsigned NOT NULL DEFAULT 0,
  `maxexp` smallint(5) unsigned NOT NULL DEFAULT 0,
  `maxgold` smallint(5) unsigned NOT NULL DEFAULT 0,
  `immune` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `imunidades` varchar(60) NOT NULL DEFAULT '',
  `elemento` varchar(10) NOT NULL DEFAULT 'neutro',
  `raridade` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `regiao_latmin` int(11) DEFAULT NULL,
  `regiao_latmax` int(11) DEFAULT NULL,
  `regiao_lonmin` int(11) DEFAULT NULL,
  `regiao_lonmax` int(11) DEFAULT NULL,
  `regiao_exclusiva` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `terrenos` varchar(100) NOT NULL DEFAULT '',
  `roubo_modo` tinyint(1) unsigned NOT NULL DEFAULT 1,
  `rouba` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `efeito` varchar(12) NOT NULL DEFAULT '',
  `efeito_chance` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `aparecimento` smallint(5) unsigned NOT NULL DEFAULT 100,
  `chancefuga` tinyint(4) NOT NULL DEFAULT -1,
  `rouba_ryou` tinyint(3) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `level` (`level`)
) ENGINE=InnoDB AUTO_INCREMENT=296 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

