(13,'Genjutsu Supremo',60,13,3,'neutro',1,0,'',0,0,100,0,40,0,'','','','',0,'batalha','',0,0,0,0,0,0),
(14,'Lótus Primária',10,16,7,'neutro',2,0,'',0,0,100,1,18,0,'','','Dois chutes ascendentes que lançam o inimigo para o alto.','',0,'batalha','',0,0,0,0,0,0),
(15,'Lótus em Cadeia',20,26,7,'neutro',3,0,'',0,0,100,2,38,0,'','','Três golpes encadeados em pleno ar, sem dar tempo de defesa.','',0,'batalha','',0,0,0,0,0,0),
(16,'Lótus Oculta',30,60,7,'neutro',3,0,'atordoar',0,1,40,3,70,0,'','','A sequência proibida: três golpes violentos que podem deixar o inimigo atordoado.','',0,'batalha','',0,0,0,0,0,0),
(17,'Escudo de Chakra',10,10,5,'neutro',1,0,'',0,0,100,0,14,0,'','','','',0,'batalha','',0,0,0,0,0,0),
(18,'Barreira de Areia',20,25,5,'neutro',1,0,'',0,0,100,0,36,0,'','','','',0,'batalha','',0,0,0,0,0,0),
(19,'Armadura de Areia',30,50,5,'neutro',1,0,'',0,0,100,0,58,0,'','','','',0,'batalha','',0,0,0,0,0,0),
(20,'Faísca de Brasa',4,12,2,'fogo',1,0,'queimadura',3,3,60,0,3,0,'','Ember Spark','Um estalar de dedos solta uma faísca que gruda na roupa do inimigo e pode deixá-lo queimando por alguns turnos.','A snap of the fingers throws a spark that clings to the enemy\'s clothes and may leave them burning for a few turns.',0,'batalha','',0,0,0,1,0,0),
(21,'Agulhas de Orvalho',6,6,2,'agua',3,0,'',0,0,100,0,6,1,'','Dewdrop Needles','Gotas de orvalho endurecidas pelo chakra são disparadas em três rajadas rápidas.','Dewdrops hardened by chakra are fired in three quick bursts.',0,'batalha','',0,0,0,1,0,0),
(22,'Pele de Casca',8,0,6,'terra',1,0,'escudo',30,3,100,3,10,0,'','Bark Skin','A pele endurece como a casca de uma árvore velha e absorve os próximos golpes.','Your skin hardens like the bark of an old tree and soaks up the next blows.',0,'batalha','',0,0,0,0,0,0),
(23,'Passo Leve como Pluma',8,0,6,'neutro',1,0,'buff_esquiva',20,3,100,3,13,2,'','Feather-Light Step','O corpo fica leve como uma pluma, tornando mais fácil desviar dos ataques.','The body becomes light as a feather, making attacks easier to dodge.',0,'batalha','',0,0,0,0,0,0),
(24,'Punho Certeiro',10,40,7,'neutro',1,0,'atordoar',0,1,30,2,16,2,'','Precise Fist','Um soco seco num ponto nervoso que às vezes deixa o inimigo tremendo, sem conseguir atacar.','A sharp punch to a nerve point that sometimes leaves the enemy shaking, unable to attack.',0,'batalha','',0,0,0,0,0,0),
(25,'Véu de Névoa Fria',12,0,6,'agua',1,0,'debuff_ataque',25,5,100,3,21,3,'','Cold Mist Veil','Uma névoa gelada embaça os olhos do inimigo: os golpes dele perdem a força.','A freezing mist clouds the enemy\'s eyes, and their blows lose their strength.',0,'batalha','',0,0,0,0,0,0),
(26,'Toque da Erva Amarga',12,10,2,'neutro',1,0,'veneno',6,4,100,0,19,0,'','Bitter Herb Touch','As pontas dos dedos, cobertas de seiva de uma erva amarga, envenenam o alvo ao toque.','Fingertips coated in the sap of a bitter herb poison the target on contact.',0,'batalha','',0,0,0,0,0,0),
(27,'Sopro Restaurador',15,20,1,'neutro',1,0,'cura_turnos',10,3,100,2,20,0,'','Restoring Breath','Uma respiração profunda guia o chakra pelas feridas, que continuam fechando nos turnos seguintes.','A deep breath guides chakra through your wounds, which keep closing over the next turns.',0,'batalha','',0,0,0,0,0,0),
(28,'Lança de Brasa',20,55,2,'fogo',1,0,'queimadura',8,3,50,0,32,1,'','Ember Lance','Uma lança de brasas comprimidas atravessa o inimigo e pode deixá-lo em chamas.','A lance of compressed embers pierces the enemy and may set them ablaze.',0,'batalha','',0,0,0,1,0,0),
(29,'Correntes de Areia',22,30,2,'terra',1,0,'atordoar',0,1,50,3,27,0,'','Sand Chains','Correntes de areia brotam do chão, ferem e podem prender o inimigo por um turno.','Chains of sand burst from the ground, wounding the enemy and possibly holding them for a turn.',0,'batalha','',0,0,0,1,0,0),
(30,'Olhar que Pesa',18,0,6,'neutro',1,0,'debuff_defesa',25,5,100,3,30,3,'','Weighing Gaze','Uma ilusão faz o inimigo sentir o próprio corpo pesado e lento: ele recebe mais dano.','An illusion makes the enemy feel heavy and sluggish, so they take more damage.',0,'batalha','',0,0,0,0,0,0),
(31,'Rasteira Dupla Veloz',26,40,7,'neutro',2,0,'',0,0,100,0,33,2,'','Swift Double Sweep','Duas rasteiras rápidas, uma atrás da outra, rentes ao chão.','Two quick sweeps, one after the other, low to the ground.',0,'batalha','',0,0,0,0,0,0),
(32,'Raiz Sedenta',28,50,2,'terra',1,40,'',0,0,100,1,37,0,'','Thirsty Root','Uma raiz sai da terra, perfura o inimigo e devolve a você parte da vida que bebeu.','A root rises from the earth, pierces the enemy and returns part of the life it drank to you.',0,'batalha','',0,0,0,1,0,0),
(33,'Foco do Falcão',20,0,6,'vento',1,0,'buff_critico',25,4,100,4,42,0,'','Falcon Focus','Você enxerga cada abertura na guarda do inimigo como um falcão vê a presa.','You see every gap in the enemy\'s guard the way a falcon sees its prey.',0,'batalha','',0,0,0,0,0,0),
(34,'Maré Ascendente',38,95,2,'agua',1,0,'debuff_ataque',15,2,100,0,48,1,'','Rising Tide','Uma onda sobe do nada, derruba o inimigo e o deixa encharcado e mais fraco.','A wave rises out of nowhere, knocks the enemy down and leaves them soaked and weaker.',0,'batalha','',0,0,0,1,0,0),
(35,'Dança das Cinzas Rubras',14,14,2,'fogo',3,0,'queimadura',5,3,70,1,10,0,'','Crimson Ash Dance','Três giros envoltos em cinzas incandescentes que costumam deixar o alvo queimando.','Three spins wrapped in glowing ash that usually leave the target burning.',0,'batalha','',0,0,0,1,0,0),
(36,'Espinhos de Gelo Lento',14,30,2,'agua',1,0,'debuff_defesa',20,3,100,1,12,1,'','Slow Ice Thorns','Espinhos de gelo se cravam no inimigo e congelam as juntas, abrindo a guarda dele.','Ice thorns sink into the enemy and freeze their joints, opening their guard.',0,'batalha','',0,0,0,1,0,0),
(37,'Sussurro Entorpecente',20,0,6,'neutro',1,0,'atordoar',0,3,70,6,18,3,'','Numbing Whisper','Uma voz que só o inimigo ouve deixa os braços dele dormentes por dois turnos.','A voice only the enemy can hear numbs their arms for two turns.',0,'batalha','',0,0,0,0,0,0),
(38,'Muralha de Barro',24,0,6,'terra',1,0,'escudo',90,4,100,5,22,0,'','Mud Rampart','Uma muralha de barro se ergue à sua frente e segura uma boa quantidade de dano.','A rampart of mud rises in front of you and holds back a good amount of damage.',0,'batalha','',0,0,0,0,0,0),
(39,'Seiva Vital',30,40,1,'agua',1,0,'cura_turnos',20,4,100,4,26,0,'','Vital Sap','O chakra corre como seiva fresca: cura na hora e continua curando por quatro turnos.','Chakra flows like fresh sap, healing at once and for four more turns.',0,'batalha','',0,0,0,0,0,0),
(40,'Ventania Cortante',30,20,2,'vento',4,0,'',0,0,100,0,30,0,'','Cutting Gale','Quatro lâminas de vento cortam o inimigo de todas as direções.','Four blades of wind slash the enemy from every direction.',0,'batalha','',0,0,0,1,0,0),
(41,'Mordida da Lua Nova',32,75,7,'neutro',1,50,'',0,0,100,2,33,2,'','New Moon Bite','Um golpe noturno que arranca a força do inimigo e a transforma na sua vida.','A night strike that tears away the enemy\'s strength and turns it into your life.',0,'batalha','',0,0,0,0,0,0),
(42,'Tempestade de Agulhas Elétricas',40,30,2,'raio',3,0,'atordoar',0,1,25,2,37,1,'Genin','Electric Needle Storm','Três ondas de agulhas eletrificadas; a descarga pode paralisar o inimigo.','Three waves of electrified needles; the discharge may paralyze the enemy.',0,'batalha','',0,0,0,1,0,0),
(43,'Bruma do Esquecimento',25,40,2,'agua',1,0,'dreno_chakra',35,1,100,2,40,3,'','Mist of Forgetting','Uma bruma confunde o inimigo e devolve a você o chakra que ele deixou escapar.','A mist confuses the enemy and gives you back the chakra they let slip.',0,'batalha','',0,0,0,1,0,0),
(44,'Sangue de Ferro',30,0,6,'neutro',1,0,'buff_defesa',40,4,100,5,44,2,'','Iron Blood','Você endurece o corpo por dentro: os golpes do inimigo perdem boa parte do efeito.','You harden your body from within, and the enemy\'s blows lose much of their effect.',0,'batalha','',0,0,0,0,0,0),
(45,'Fúria do Vulcão Adormecido',60,150,2,'fogo',1,0,'queimadura',20,3,80,3,52,1,'Chuunin','Fury of the Sleeping Volcano','O chão se abre e cospe lava sobre o inimigo, que continua em chamas.','The ground splits open and spits lava over the enemy, who keeps burning.',0,'batalha','',0,0,0,1,0,0),
(46,'Mil Raízes Famintas',65,45,2,'terra',3,30,'',0,0,100,3,58,0,'Chuunin','Thousand Hungry Roots','Raízes famintas atacam três vezes e repartem com você a vida que sugaram.','Hungry roots strike three times and share the life they drained with you.',0,'batalha','',0,0,0,1,0,0),
(47,'Lamento da Serpente Pálida',50,60,2,'neutro',1,0,'veneno',30,8,100,4,63,3,'','Pale Serpent’s Lament','A ilusão de uma serpente pálida morde o inimigo, e o veneno imaginário dói de verdade.','The illusion of a pale serpent bites the enemy, and the imaginary venom hurts for real.',0,'batalha','',0,0,0,0,0,0),
(48,'Céu Rachado',80,200,2,'raio',1,0,'atordoar',0,1,40,4,70,0,'Chuunin','Cracked Sky','Um relâmpago racha o céu ao meio e cai sobre o inimigo, que pode ficar paralisado.','A lightning bolt splits the sky in two and falls on the enemy, who may be left paralyzed.',0,'batalha','',0,0,0,1,0,0),
(49,'Forma do Guerreiro Ancestral',70,0,6,'neutro',1,0,'buff_ataque',50,5,100,8,76,2,'Chuunin','Ancestral Warrior Form','Você desperta a postura de guerreiros antigos e bate muito mais forte por cinco turnos.','You awaken the stance of ancient warriors and hit much harder for five turns.',0,'batalha','',0,0,0,0,0,0),
(50,'Selo das Mil Lanternas',38,45,2,'fogo',3,0,'queimadura',15,3,70,3,30,0,'','Seal of a Thousand Lanterns','Centenas de pequenas chamas presas em papel de selo voam em espiral e explodem uma a uma contra o inimigo, deixando-o em brasa.','Hundreds of tiny flames trapped in sealing paper spiral through the air and burst one by one against the enemy, leaving it smouldering.',1,'batalha','',0,0,0,1,0,0),
(51,'Abraço da Maré Funda',50,260,1,'agua',1,0,'cura_turnos',40,3,100,4,42,0,'','Embrace of the Deep Tide','Uma onda de chakra frio envolve o corpo e fecha as feridas; a maré continua subindo por alguns turnos.','A wave of cold chakra wraps the body and closes its wounds; the tide keeps rising for a few turns.',1,'batalha','',0,0,0,0,0,0),
(52,'Voz do Trovão Distante',60,170,2,'raio',1,0,'debuff_defesa',35,3,100,3,50,0,'','Voice of the Distant Thunder','Um estrondo que chega antes do raio: o golpe racha a guarda do inimigo, que passa a receber mais dano.','A rumble that arrives before the lightning: the blow cracks the enemy guard, which then takes more damage.',1,'batalha','',0,0,0,1,0,0),
(53,'Pele do Titã de Basalto',55,0,6,'terra',1,0,'escudo',500,3,100,5,60,0,'Chuunin','Basalt Titan Hide','Placas de rocha vulcânica crescem sobre a pele como a carapaça do Titã de Pedra, absorvendo os golpes.','Plates of volcanic rock grow over the skin like the Stone Titan shell, soaking up incoming blows.',1,'batalha','',0,0,0,0,0,0),
(54,'Coração do Leviatã Abissal',90,240,2,'agua',1,20,'atordoar',0,1,50,5,68,0,'Chuunin','Heart of the Abyssal Leviathan','A pressão do fundo do mar esmaga o inimigo de uma vez: parte da força volta para quem usou e o alvo pode ficar atordoado.','The pressure of the ocean floor crushes the enemy at once: some of the strength flows back to the user and the target may be stunned.',1,'batalha','',0,0,0,1,0,0),
(55,'Rugido do Dragão de Cinzas',95,130,2,'fogo',2,25,'queimadura',30,3,100,4,76,0,'Chuunin','Roar of the Ash Dragon','Dois jatos de fogo negro em forma de dragão mordem o inimigo, roubam vida e deixam cinzas ardendo por vários turnos.','Two jets of black dragon-shaped fire bite the enemy, steal life and leave embers burning for several turns.',1,'batalha','',0,0,0,1,0,0),
(56,'Punho Endurecido',6,25,7,'neutro',2,0,'',0,0,100,0,11,2,'','Hardened Fist','Dois socos secos, com o punho endurecido pelo chakra, no mesmo ponto do corpo do inimigo.','Two sharp punches, the fist hardened by chakra, on the same spot of the enemy’s body.',0,'batalha','',0,0,0,0,0,0),
(57,'Investida do Javali Cinzento',16,55,7,'neutro',1,0,'atordoar',0,1,35,2,24,2,'','Grey Boar Charge','Uma arrancada de ombro baixo que derruba o inimigo; às vezes ele fica tonto e perde o próximo ataque.','A low-shoulder charge that knocks the enemy over; sometimes they are left dazed and lose their next attack.',0,'batalha','',0,0,0,0,0,0),
(58,'Sequência dos Cem Passos',30,30,7,'neutro',4,0,'',0,0,100,2,47,2,'','Hundred-Step Barrage','O corpo some e reaparece em volta do inimigo, acertando quatro golpes antes que ele consiga reagir.','Your body vanishes and reappears around the enemy, landing four blows before they can react.',0,'batalha','',0,0,0,0,0,0),
(59,'Golpe da Fera Faminta',45,150,7,'neutro',1,25,'',0,0,100,3,66,2,'','Starving Beast Strike','Um golpe selvagem que arranca a força do inimigo e a devolve como vida para quem ataca.','A savage blow that tears the strength out of the enemy and returns it as life to the attacker.',0,'batalha','',0,0,0,0,0,0),
(60,'Lâminas de Vento Gêmeas',9,12,2,'vento',2,0,'',0,0,100,0,8,1,'','Twin Wind Blades','Duas lâminas de ar comprimido cortam o inimigo em X.','Two blades of compressed air slash the enemy in an X.',0,'batalha','',0,0,0,1,0,0),
(61,'Pilar de Rocha Ascendente',24,45,2,'terra',1,0,'debuff_defesa',11,3,100,1,26,1,'','Rising Rock Pillar','Um pilar de pedra brota do chão sob o inimigo e racha a sua guarda.','A stone pillar bursts from the ground beneath the enemy and cracks their guard.',0,'batalha','',0,0,0,1,0,0),
(62,'Serpente de Relâmpago',45,63,2,'raio',3,0,'atordoar',0,1,25,2,53,1,'','Lightning Serpent','Uma serpente de raios morde três vezes; o choque pode paralisar o alvo.','A serpent of lightning bites three times; the shock may paralyze the target.',0,'batalha','',0,0,0,1,0,0),
(63,'Cometa de Brasa Errante',80,260,2,'fogo',1,0,'queimadura',25,3,100,4,68,1,'','Wandering Ember Comet','Uma esfera de fogo cai do alto como um cometa e deixa o inimigo em chamas.','A sphere of fire falls from above like a comet and leaves the enemy ablaze.',0,'batalha','',0,0,0,1,0,0),
(64,'Eco da Sombra Lenta',8,22,2,'neutro',1,0,'debuff_ataque',20,4,100,2,9,3,'','Echo of the Slow Shadow','O inimigo passa a ver a própria sombra um instante atrasada e hesita a cada golpe.','The enemy starts seeing their own shadow a moment late and hesitates with every blow.',0,'batalha','',0,0,0,0,0,0),
(65,'Labirinto de Espelhos Partidos',18,0,6,'neutro',1,0,'atordoar',0,3,55,6,24,3,'','Labyrinth of Broken Mirrors','Espelhos quebrados cercam o inimigo; perdido entre os reflexos, ele pode ficar sem atacar por dois turnos.','Broken mirrors surround the enemy; lost among the reflections, they may be unable to attack for two turns.',0,'batalha','',0,0,0,0,0,0),
(66,'Pesadelo Rastejante',28,30,2,'neutro',1,0,'veneno',20,7,100,2,46,3,'','Creeping Nightmare','Um pesadelo entra pela pele do inimigo e continua a feri-lo por dentro durante vários turnos.','A nightmare seeps in through the enemy\'s skin and keeps hurting them from within for several turns.',0,'batalha','',0,0,0,0,0,0),
(67,'Coroa de Espinhos Ilusórios',50,170,2,'neutro',1,0,'debuff_defesa',30,7,100,4,66,3,'','Crown of Illusory Thorns','Espinhos que só o inimigo vê se cravam na sua cabeça: ele baixa a guarda e passa a sofrer mais dano.','Thorns that only the enemy can see dig into their head: they lower their guard and take more damage.',0,'batalha','',0,0,0,0,0,0),
(90,'Passo Veloz: Pluma',3,0,6,'vento',1,0,'',0,0,100,0,30,0,'','Swift Step: Feather','O chakra se concentra na sola dos pés e o corpo fica leve como uma pluma: cada passo cobre duas casas do mapa. Fica ligado (gastando Chakra a cada passo) até você desligar.','Chakra gathers in the soles of your feet and your body turns light as a feather: every step covers two map tiles. It stays on (spending Chakra on each step) until you turn it off.',0,'menu','passo',0,1,0,0,0,0),
(91,'Passo Veloz: Cometa',5,0,6,'vento',1,0,'',0,0,100,0,0,0,'Chuunin','Swift Step: Comet','Um rastro de vento segue o ninja como a cauda de um cometa: cada passo cobre três casas. Gasta Chakra e Pontos de Viagem a cada passo até ser desligado.','A trail of wind follows the ninja like a comet tail: every step covers three tiles. It spends Chakra and Travel Points on each step until it is turned off.',1,'menu','passo',0,2,0,0,1,0),
(92,'Invocação de Suprimentos: Bolsa',15,0,6,'neutro',1,0,'',0,0,100,0,8,0,'','Supply Summoning: Pouch','Um selo desenhado na palma abre um pequeno depósito esquecido: às vezes sai uma poção ou um equipamento simples, às vezes só poeira.','A seal drawn on the palm opens a small forgotten storeroom: sometimes a potion or a simple piece of gear comes out, sometimes only dust.',0,'menu','suprimentos',0,1,0,0,0,10),
(93,'Invocação de Suprimentos: Baú',30,0,6,'neutro',1,0,'',0,0,100,0,25,0,'','Supply Summoning: Chest','O selo alcança os baús de viagem dos mercadores ambulantes. Mais chance de encontrar algo útil.','The seal reaches into the travel chests of wandering merchants. A better chance of finding something useful.',0,'menu','suprimentos',0,2,0,0,0,20),
(94,'Invocação de Suprimentos: Armazém',55,0,6,'neutro',1,0,'',0,0,100,0,45,0,'','Supply Summoning: Storehouse','Um círculo de selos se abre no chão e puxa caixas de um armazém distante. Itens melhores, mas o chakra cobrado é alto.','A circle of seals opens on the ground and pulls crates out of a distant storehouse. Better items, but the chakra cost is high.',0,'menu','suprimentos',0,3,0,0,0,40),
(95,'Invocação de Suprimentos: Cofre do Clã',90,0,6,'neutro',1,0,'',0,0,100,0,0,0,'Chuunin','Supply Summoning: Clan Vault','O selo esquecido do clã dos guardiões abre o cofre onde gerações guardaram armas e amuletos. Só quem venceu a provação do cofre conhece os sinais.','The forgotten seal of the warden clan opens the vault where generations stored weapons and amulets. Only those who passed the vault trial know the signs.',1,'menu','suprimentos',0,4,0,0,0,60),
(96,'Rugido da Montanha Adormecida',70,260,2,'terra',1,0,'atordoar',0,1,40,4,0,0,'Chuunin','Roar of the Sleeping Mountain','Só no modo Senjutsu: a energia natural da terra sobe pelas pernas e explode num rugido que racha o chão sob o inimigo, que pode ficar atordoado.','Sage Mode only: natural energy rises from the earth through your legs and bursts into a roar that splits the ground under the enemy, which may be stunned.',1,'batalha','',1,0,25,1,0,0),
(97,'Chuva de Pétalas do Bosque Antigo',60,115,2,'vento',3,15,'',0,0,100,3,0,0,'Chuunin','Petal Rain of the Old Grove','Só no modo Senjutsu: pétalas afiadas como lâminas cortam o inimigo três vezes e devolvem parte da vida a quem as chamou.','Sage Mode only: razor-sharp petals slash the enemy three times and return part of the life to the one who called them.',1,'batalha','',1,0,20,1,0,0),
(98,'Casca do Carvalho Milenar',50,0,6,'terra',1,0,'escudo',700,3,100,5,0,0,'Chuunin','Bark of the Thousand-Year Oak','Só no modo Senjutsu: uma casca grossa de carvalho cresce sobre a pele e absorve uma grande quantidade de dano.','Sage Mode only: thick oak bark grows over the skin and soaks up a large amount of damage.',1,'batalha','',1,0,30,0,0,0),
(99,'Respiração da Terra Viva',0,600,1,'neutro',1,0,'',0,0,100,0,0,0,'Chuunin','Breath of the Living Earth','Só no modo Senjutsu, fora de lutas: o ninja respira junto com a terra e as feridas se fecham. Gasta Pontos Naturais em vez de Chakra.','Sage Mode only, outside fights: the ninja breathes together with the earth and wounds close. Costs Natural Points instead of Chakra.',1,'menu','',1,0,60,0,0,15),
(100,'Lança do Relâmpago Negro',48,125,2,'raio',1,0,'debuff_defesa',20,2,60,3,35,0,'Chuunin','Black Lightning Spear','O chakra de raio é comprimido até escurecer e disparado como uma lança: o golpe atravessa a guarda e pode deixar o inimigo mais vulnerável por alguns turnos.','Lightning chakra is compressed until it turns dark and hurled like a spear: the blow pierces the guard and may leave the enemy more vulnerable for a few turns.',1,'batalha','',0,0,0,1,0,0),
(101,'Chute do Redemoinho',4,14,7,'neutro',1,0,'',0,0,100,0,5,0,'','','Um chute girando que acerta com o peso do corpo inteiro.','',0,'batalha','',0,0,0,0,0,0),
(102,'Rajada de Punhos',9,9,7,'neutro',3,0,'',0,0,100,1,15,0,'','','Três socos rápidos no mesmo ponto.','',0,'batalha','',0,0,0,0,0,0),
(103,'Martelo Descendente',18,60,7,'neutro',1,0,'atordoar',0,1,30,2,28,0,'','','Salta e desce o calcanhar como um martelo; às vezes deixa o inimigo atordoado.','',0,'batalha','',0,0,0,0,0,0),
(104,'Palma do Tigre Furioso',26,85,7,'neutro',1,0,'debuff_defesa',25,2,100,2,43,0,'','','Uma palma que quebra a guarda: o inimigo fica com a defesa enfraquecida.','',0,'batalha','',0,0,0,0,0,0),
(105,'Vendaval de Mil Chutes',40,40,7,'neutro',4,0,'',0,0,100,2,60,0,'','','Quatro chutes tão rápidos que parecem um só.','',0,'batalha','',0,0,0,0,0,0),
(106,'Punho do Dragão Desperto',60,230,7,'neutro',1,10,'',0,0,100,3,74,0,'','','O golpe final: um soco que devolve um pouco da força como vida.','',0,'batalha','',0,0,0,0,0,0),
(107,'Fúria do Chakra Interior',10,10,4,'neutro',1,0,'',0,0,100,0,18,0,'','','O chakra corre mais forte pelos músculos: +10% de dano até o fim da luta.','',0,'batalha','',0,0,0,0,0,0),
(108,'Portão do Chakra Desperto',20,25,4,'neutro',1,0,'',0,0,100,0,38,0,'','','Abre um portão interno de chakra: +25% de dano até o fim da luta.','',0,'batalha','',0,0,0,0,0,0),
(109,'Ímpeto do Chakra Ardente',30,50,4,'neutro',1,0,'',0,0,100,0,70,0,'','','O chakra queima por dentro: +50% de dano até o fim da luta.','',0,'batalha','',0,0,0,0,0,0),
(110,'Gêiser da Fenda Fervente',32,52,2,'agua',2,0,'queimadura',10,3,60,2,35,1,'','Boiling Rift Geyser','A terra se abre sob o inimigo e dois jatos de água fervente o atingem; o vapor pode deixar queimaduras.','The ground splits beneath the enemy and two jets of boiling water strike them; the steam may leave burns.',0,'batalha','',0,0,0,1,0,0),
(111,'Ciclone das Folhas Cortantes',58,50,2,'vento',4,0,'debuff_defesa',15,3,100,3,62,1,'','Cyclone of Cutting Leaves','Um ciclone carregado de folhas afiadas como lâminas corta o inimigo quatro vezes e abre brechas na sua guarda.','A cyclone full of razor-sharp leaves slashes the enemy four times and opens gaps in their guard.',0,'batalha','',0,0,0,1,0,0),
(112,'Joelhada Contida',20,80,7,'neutro',1,0,'atordoar',0,1,35,2,39,2,'','Restrained Knee Strike','Toda a força do corpo concentrada num só joelho que estala no impacto; o inimigo pode ficar tonto.','The whole body’s strength focused into one knee that cracks on impact; the enemy may be left dizzy.',0,'batalha','',0,0,0,0,0,0),
(113,'Postura da Montanha que Respira',35,0,6,'neutro',1,0,'cura_turnos',60,4,100,6,63,2,'','Breathing Mountain Stance','Pés firmes e respiração lenta: o corpo fecha os ferimentos aos poucos, turno após turno.','Firm feet and slow breathing: the body closes its wounds little by little, turn after turn.',0,'batalha','',0,0,0,0,0,0),
(114,'Lamparina que Bebe a Mente',24,36,2,'neutro',1,0,'dreno_chakra',30,1,100,2,41,3,'','Mind-Drinking Lantern','Uma lamparina ilusória acende diante dos olhos do inimigo e suga o chakra da sua mente.','An illusory lantern lights up before the enemy\'s eyes and sucks the chakra from their mind.',0,'batalha','',0,0,0,0,0,0),
(115,'Teia dos Medos Antigos',38,0,6,'neutro',1,0,'veneno',40,7,100,5,64,3,'','Web of Ancient Fears','Fios invisíveis prendem o inimigo aos seus piores medos, que o corroem por vários turnos.','Invisible threads bind the enemy to their worst fears, which eat away at them for several turns.',0,'batalha','',0,0,0,0,0,0),
(116,'Estacas de Pedra Rasteira',15,32,2,'terra',1,0,'debuff_defesa',12,2,60,1,14,1,'','Creeping Stone Stakes','Estacas de pedra brotam do chão sob o inimigo e racham a guarda dele.','Stone stakes burst from the ground under the enemy and crack their guard.',0,'batalha','',0,0,0,1,0,0),
(117,'Muralha de Pedra Esmagadora',36,85,2,'terra',1,0,'atordoar',0,1,30,2,45,1,'','Crushing Stone Wall','Uma muralha de pedra tomba sobre o alvo e pode deixá-lo atordoado.','A stone wall topples onto the target and may leave it stunned.',0,'batalha','',0,0,0,1,0,0),
(118,'Corrente Elétrica Encadeada',20,18,2,'raio',3,0,'',0,0,100,1,22,1,'','Chained Electric Current','Três descargas em sequência, saltando de um ponto ao outro do corpo do inimigo.','Three discharges in a row, jumping across the enemy’s body.',0,'batalha','',0,0,0,1,0,0),
(119,'Lâmina de Vento Cortante',24,55,2,'vento',1,0,'debuff_defesa',15,3,70,1,30,1,'','Cutting Wind Blade','Uma lâmina de ar comprimido corta fundo e abre a defesa do alvo.','A blade of compressed air cuts deep and opens the target’s defense.',0,'batalha','',0,0,0,1,0,0),
(120,'Punho Implacável',14,45,7,'neutro',1,0,'debuff_defesa',15,2,60,1,20,2,'','Relentless Fist','Uma sequência de socos no mesmo ponto que racha a guarda do inimigo.','A flurry of punches on the same spot that cracks the enemy’s guard.',0,'batalha','',0,0,0,0,0,0),
(121,'Chute Giratório Quebrante',20,60,7,'neutro',1,0,'debuff_ataque',15,2,60,1,28,2,'','Breaking Spin Kick','Um chute giratório pesado que tira a força dos golpes do alvo.','A heavy spinning kick that saps the target’s striking power.',0,'batalha','',0,0,0,0,0,0),
(122,'Investida do Búfalo',28,85,7,'neutro',1,0,'atordoar',0,1,35,2,40,2,'','Buffalo Charge','O corpo inteiro avança de ombro contra o inimigo, como um búfalo em disparada.','The whole body slams shoulder-first into the enemy, like a stampeding buffalo.',0,'batalha','',0,0,0,0,0,0),
(123,'Ilusão das Brasas Fantasmas',20,28,2,'fogo',1,0,'queimadura',10,5,100,2,27,3,'','Phantom Ember Illusion','O inimigo sente brasas que não existem queimando a pele.','The enemy feels embers that are not there burning their skin.',0,'batalha','',0,0,0,1,0,0),
(124,'Miragem do Vendaval',22,0,6,'vento',1,0,'debuff_ataque',30,6,100,4,35,3,'','Gale Mirage','Uma ventania ilusória embaralha os sentidos e enfraquece os ataques do alvo.','An illusory gale scrambles the senses and weakens the target’s attacks.',0,'batalha','',0,0,0,0,0,0),
(125,'Pesadelo da Terra Movediça',34,55,2,'terra',1,0,'debuff_defesa',25,6,100,4,50,3,'','Quicksand Nightmare','O alvo sente o chão engolir suas pernas e baixa a guarda em pânico.','The target feels the ground swallowing their legs and drops their guard in panic.',0,'batalha','',0,0,0,1,0,0),
(126,'Eco do Trovão Ilusório',40,70,2,'raio',1,0,'atordoar',0,3,45,5,56,3,'','Illusory Thunder Echo','Um trovão que só o inimigo ouve; o estrondo pode deixá-lo paralisado.','A thunderclap only the enemy hears; the roar may leave them paralyzed.',0,'batalha','',0,0,0,1,0,0);
DROP TABLE IF EXISTS `naruto_suprimentos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `naruto_suprimentos` (
  `tier` tinyint(3) unsigned NOT NULL,
  `chance_falha` tinyint(3) unsigned NOT NULL DEFAULT 40 COMMENT '% de a invocação não trazer nada',
  `preco_max` mediumint(8) unsigned NOT NULL DEFAULT 0 COMMENT 'itens de loja com buycost até este valor (0 = nenhum)',
  `nivel_max_drop` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'drops com mlevel até este nível (0 = nenhum)',
  `pocao_max` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'poções de drop que recuperam até este valor (0 = nenhuma)',
  `peso_loja` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `peso_drop` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `peso_pocao` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `excluir` varchar(255) NOT NULL DEFAULT '' COMMENT 'ids fora do sorteio: i12,d45 (i = items, d = drops)',
  PRIMARY KEY (`tier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

