CREATE TABLE `naruto_temporada_pontos` (
  `temporada` int(10) unsigned NOT NULL,
  `usuario` int(10) unsigned NOT NULL,
  `pontos` int(10) unsigned NOT NULL DEFAULT 0,
  `vitorias` int(10) unsigned NOT NULL DEFAULT 0,
  `derrotas` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`temporada`,`usuario`),
  KEY `ordem` (`temporada`,`pontos`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

